import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, color, uniform, mix, float, sampler2D, texture, time as timeNode, smoothstep, fract, sin, cos, PI } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, TorusKnotGeometry, CylinderGeometry, PlaneGeometry, BufferGeometry, BufferAttribute, Vector3, Color, Object3D } = ctx.THREE;

  const group = new Group();
  const timelines = [];
  const disposables = [];

  // ============================================================================
  // BACKDROP GRADIENT PLANE (z=-3, 7x6 units)
  // ============================================================================
  const backdropGeo = new PlaneGeometry(7, 6);

  const gradientStops = config.intent?.visualSpec?.colors?.gradientStops || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ];

  const gradientU = uniform(uv().y);
  let gradientExpr = color(new Color(gradientStops[0].hex));

  for (let i = 1; i < gradientStops.length; i++) {
    const prevStop = gradientStops[i - 1];
    const currStop = gradientStops[i];
    const range = currStop.at - prevStop.at;
    const rangeStart = prevStop.at;

    const t = smoothstep(float(rangeStart), float(currStop.at), gradientU);
    gradientExpr = mix(
      gradientExpr,
      color(new Color(currStop.hex)),
      t
    );
  }

  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradientExpr;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3;
  backdrop.castShadow = false;
  backdrop.receiveShadow = false;
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ============================================================================
  // TORUS KNOT WITH BRUSHED METAL PBR
  // ============================================================================
  const knobGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);

  // Create imperfection: procedural scratch-noise normal map
  const scratchNoiseScale = 12.0;
  const scratchStrength = 0.15;
  const scratchNormal = mix(
    vec3(0.5, 0.5, 1.0),
    vec3(
      sin(uv().x * scratchNoiseScale + timeNode.mul(0.3)) * 0.5 + 0.5,
      sin(uv().y * scratchNoiseScale + timeNode.mul(0.2)) * 0.5 + 0.5,
      1.0
    ),
    float(scratchStrength)
  );

  // Roughness jitter (2% value variation)
  const roughnessJitter = mix(
    float(0.98),
    float(1.02),
    sin(uv().x * 8.0 + uv().y * 8.0 + timeNode.mul(0.1)) * 0.5 + 0.5
  );

  // Load brushed metal map
  let roughnessMapNode = float(0.55);
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    roughnessMapNode = sampler2D(tex, uv());
    knobMat.roughnessNode = mix(
      float(0.55),
      roughnessMapNode.mul(float(0.9)),
      roughnessJitter
    );
    knobMat.needsUpdate = true;
  }).catch(() => {
    // fallback: no map
  });

  const knobMat = new MeshStandardNodeMaterial();
  knobMat.color = new Color('#e8ecf2');
  knobMat.roughness = 0.55;
  knobMat.metalness = 0.55;
  knobMat.clearcoat = 0.22;
  knobMat.clearcoatRoughness = 0.35;
  knobMat.anisotropy = 0.9;
  knobMat.anisotropyRotation = Math.PI / 2; // 90 deg rotation to tube direction
  knobMat.normalNode = scratchNormal;
  knobMat.normalScale = vec3(scratchStrength, scratchStrength, 1.0);

  const knob = new Mesh(knobGeo, knobMat);
  knob.position.y = 0.4;
  knob.castShadow = true;
  knob.receiveShadow = true;
  group.add(knob);
  disposables.push(knobGeo, knobMat);

  // ============================================================================
  // CYLINDRICAL PEDESTAL WITH CHAMFERED TOP
  // ============================================================================
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 48, 2);

  const pedestalMat = new MeshStandardNodeMaterial();
  pedestalMat.color = new Color('#14141a');
  pedestalMat.roughness = 0.7;
  pedestalMat.metalness = 0.35;
  pedestalMat.envMapIntensity = 0.7;

  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.y = -0.3; // y=-0.35 (top) => center at -0.3
  pedestal.castShadow = true;
  pedestal.receiveShadow = true;
  group.add(pedestal);
  disposables.push(pedestalGeo, pedestalMat);

  // Chamfered top edge (separate bevel geometry)
  const chamferGeo = new CylinderGeometry(1.1, 1.08, 0.03, 48, 2);
  const chamferMat = new MeshStandardNodeMaterial();
  chamferMat.color = new Color('#16161d');
  chamferMat.roughness = 0.6;
  chamferMat.metalness = 0.4;

  const chamfer = new Mesh(chamferGeo, chamferMat);
  chamfer.position.y = -0.335; // top surface catches key light
  chamfer.castShadow = true;
  chamfer.receiveShadow = true;
  group.add(chamfer);
  disposables.push(chamferGeo, chamferMat);

  // ============================================================================
  // CONTACT SHADOW (radial gradient plane)
  // ============================================================================
  const shadowGeo = new PlaneGeometry(3.0, 3.0, 32, 32);
  const shadowPositions = shadowGeo.attributes.position.array;
  const shadowColors = new Float32Array(shadowGeo.attributes.position.array.length);

  for (let i = 0; i < shadowPositions.length; i += 3) {
    const x = shadowPositions[i];
    const z = shadowPositions[i + 2];
    const dist = Math.sqrt(x * x + z * z);
    const falloff = Math.max(0, 1 - dist / 0.75); // radius 1.5, falloff over 0.4
    const opacity = 0.6 * falloff * falloff; // quadratic falloff

    shadowColors[i] = 0;
    shadowColors[i + 1] = 0;
    shadowColors[i + 2] = 0;
    shadowColors[i + 3] = opacity;
  }

  shadowGeo.setAttribute('color', new BufferAttribute(shadowColors, 4));

  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  shadowMat.colorNode = color(new Color(0x000000)).mul(float(0.6));

  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.y = -0.36;
  shadow.rotation.x = -Math.PI / 2;
  shadow.receiveShadow = false;
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ============================================================================
  // LIGHTING
  // ============================================================================
  const ambientLight = new ctx.THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambientLight);

  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.2, 1.4, 1.0);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 1024;
  keyLight.shadow.mapSize.height = 1024;
  keyLight.shadow.camera.far = 10;
  keyLight.shadow.camera.near = 0.1;
  group.add(keyLight);

  const rimLight = new ctx.THREE.DirectionalLight(0xff6b35, 0.8); // warm accent rim
  rimLight.position.set(-1.5, 0.8, -1.2);
  group.add(rimLight);

  // ============================================================================
  // TEXT CONTENT
  // ============================================================================
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  let headlineText = 'Material study 03';
  let captionText = 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT';

  for (const item of textItems) {
    if (item.role === 'headline' || item.typography?.fontSize === 68) {
      headlineText = item.text || headlineText;
    } else if (item.role === 'caption' || item.typography?.fontSize === 18) {
      captionText = item.text || captionText;
    }
  }

  const headlineObj = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center'
  });
  headlineObj.position.y = -1.2;
  headlineObj.position.z = 0.1;
  group.add(headlineObj);

  const captionObj = ctx.fontAtlas.createText(captionText, {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.08 * 18
  });
  captionObj.position.y = -1.6;
  captionObj.position.z = 0.1;
  group.add(captionObj);

  // ============================================================================
  // ANIMATION: ORBIT PRIMITIVE (load trigger)
  // ============================================================================
  const orbitPrimitive = ctx.primitives['orbit'](group, {
    speed: 0.1,
    radius: 0.4,
    trigger: 'load'
  });

  if (orbitPrimitive && orbitPrimitive.timeline) {
    timelines.push(orbitPrimitive.timeline);
  }

  // ============================================================================
  // CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    timelines.forEach(tl => {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    });

    if (orbitPrimitive && typeof orbitPrimitive.cleanup === 'function') {
      orbitPrimitive.cleanup();
    }

    disposables.forEach(res => {
      if (res && typeof res.dispose === 'function') {
        res.dispose();
      }
    });

    group.traverse(child => {
      if (child.geometry && typeof child.geometry.dispose === 'function') {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => {
            if (m && typeof m.dispose === 'function') {
              m.dispose();
            }
          });
        } else if (typeof child.material.dispose === 'function') {
          child.material.dispose();
        }
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
